public final class MainActivity extends Activity {
    private final ExecutorService io=Executors.newFixedThreadPool(4),streams=Executors.newFixedThreadPool(12);
    private final Map<String,WebView> views=new ConcurrentHashMap<>();private final Map<String,CompletableFuture<Void>> acknowledgements=new ConcurrentHashMap<>();
    private final Map<String,Write> writes=new ConcurrentHashMap<>();private final Map<Integer,ValueCallback<Uri[]>> pickers=new HashMap<>();
    private FrameLayout root,content;private LinearLayout toolbar;private TextView ttsButton,toolbarTitle;private volatile String surface="home";private int nextPicker=1000;
    ArchiveStore store;PackLibrary packs;SecretVault vault;NetworkBroker network;PhoneRooms rooms;RoomDiscovery discovery;SpeechPlayer speech;Sensors sensors;HomeConversation conversation;
    private File exportFile;private CompletableFuture<JSONObject> exportResult;private String stagedModel="",modelNonce="";private JSONObject bodyState=new JSONObject();private JSONArray availableActions=new JSONArray();
    private volatile boolean destroyed=false,suspended=false,stageEditing=false;
    private final ScheduledExecutorService interactionQueue=Executors.newSingleThreadScheduledExecutor();private final ArrayDeque<JSONObject> pendingTouches=new ArrayDeque<>();
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);getWindow().setStatusBarColor(Color.rgb(35,29,45));getWindow().setNavigationBarColor(Color.rgb(25,21,33));
        try{File privateRoot=new File(getFilesDir(),"QibanCompanion");store=new ArchiveStore(privateRoot);packs=new PackLibrary(new File(privateRoot,"libraries"));vault=new SecretVault(this);network=new NetworkBroker(store,vault);rooms=new PhoneRooms();discovery=new RoomDiscovery(this);speech=new SpeechPlayer(this,store,packs,network,this::speechEvent);conversation=new HomeConversation(this);sensors=new Sensors(this);
            root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(35,29,45));root.setOnApplyWindowInsetsListener((v,insets)->{int top=insets.getSystemWindowInsetTop(),bottom=insets.getStableInsetBottom();if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());top=bars.top;bottom=bars.bottom;}root.setPadding(0,top,0,bottom);return insets;});LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);toolbar.setBackgroundColor(Color.rgb(248,248,253));Button back=new Button(this);back.setText("‹ 陪伴");back.setOnClickListener(v->show("home"));toolbar.addView(back);TextView title=new TextView(this);toolbarTitle=title;title.setText("通讯");title.setTextColor(Color.DKGRAY);toolbar.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));ttsButton=new TextView(this);ttsButton.setTextColor(Color.rgb(83,73,147));ttsButton.setPadding(dp(8),0,dp(8),0);ttsButton.setOnClickListener(v->safe(()->toggleTTS()));toolbar.addView(ttsButton);Button menu=new Button(this);menu.setText("•••");menu.setOnClickListener(this::showMenu);toolbar.addView(menu);column.addView(toolbar,new LinearLayout.LayoutParams(-1,dp(50)));content=new FrameLayout(this);column.addView(content,new LinearLayout.LayoutParams(-1,0,1));root.addView(column);setContentView(root);show("home");refreshTTS();
            interactionQueue.scheduleWithFixedDelay(this::drainTouches,350,350,TimeUnit.MILLISECONDS);
        }catch(Exception e){TextView failure=new TextView(this);failure.setPadding(dp(24),dp(48),dp(24),dp(24));failure.setText("本地资料未能打开，原文件已保留。\n"+e.getMessage());setContentView(failure);}
    }
    private interface Action {void run()throws Exception;}
    private void safe(Action action){try{action.run();}catch(Exception e){notice(e.getMessage());}}
    int dp(int n){return(int)(getResources().getDisplayMetrics().density*n+.5f);}
    ViewGroup overlay(){return root;}
    void clearTouches(){synchronized(pendingTouches){pendingTouches.clear();}}
    private void drainTouches(){try{if(destroyed||suspended||!surface.equals("home")||stageEditing||conversation.busy()||speech.isBusy())return;ArrayList<String> text=new ArrayList<>();synchronized(pendingTouches){while(!pendingTouches.isEmpty()){JSONObject t=pendingTouches.removeFirst();if(System.currentTimeMillis()-t.optLong("at")<30000)text.add(t.optString("text"));}}if(text.isEmpty())return;conversation.send(json("text",String.join("\n",text),"observation",true),availableActions,bodyState,sensors);}catch(Exception e){notice(e.getMessage());}}
    private WebView create(String name)throws Exception {
        if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))throw new IOException("请先更新 Android System WebView / Chrome，再打开栖伴。");
        WebView view=new WebView(this);view.setBackgroundColor(name.equals("home")?Color.rgb(35,29,45):Color.WHITE);WebSettings settings=view.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMediaPlaybackRequiresUserGesture(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportMultipleWindows(false);settings.setBuiltInZoomControls(false);settings.setTextZoom(100);
        String origin="https://"+name+".qiban.local";LocalOrigin files=new LocalOrigin(this,packs);
        WebViewCompat.addWebMessageListener(view,"qibanAndroid",Set.of(origin),(web,message,sourceOrigin,isMainFrame,reply)->{
            if(!isMainFrame||!origin.equals(sourceOrigin.toString()))return;
            try{String raw=message.getData();if(raw==null||raw.length()>64*1024*1024)throw new IOException("本地消息过大。");JSONObject envelope=new JSONObject(raw);String id=envelope.optString("id"),channel=envelope.optString("channel");if(channel.equals("ack")){CompletableFuture<Void> ack=acknowledgements.remove(id);if(ack!=null)ack.complete(null);return;}
                if(!channel.equals(name.equals("chat")?"qibanChat":name.equals("game")?"qibanGame":"home")&&!(name.equals("home")&&channel.equals("snowbreak")))throw new IOException("此页面不能调用该功能。");
                JSONObject body=envelope.getJSONObject("body");io.execute(()->{try{JSONObject result=command(name,channel,body);respond(reply,id,result,null);}catch(Exception|LinkageError error){respond(reply,id,null,cleanError(error));}});
            }catch(Exception error){respond(reply,"",null,error.getMessage());}
        });
        view.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(!"https".equals(u.getScheme())||!Objects.equals(u.getHost(),name+".qiban.local"))return null;try{return files.open(name,u.getPath());}catch(Exception e){return LocalOrigin.error(404,"资源未能读取："+u.getPath());}}
            @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(("https://"+u.getHost()).equals(origin))return false;if(request.hasGesture()&&List.of("http","https").contains(u.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}
            @Override public boolean onRenderProcessGone(WebView v,RenderProcessGoneDetail detail){network.cancelAll();speech.stop();content.removeView(v);views.remove(name);v.destroy();notice("显示进程已重启，记录仍保留。再次打开页面即可恢复。");if(name.equals("home"))safe(()->show("home"));return true;}
        });
        view.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView web,ValueCallback<Uri[]> result,FileChooserParams params){int id=nextPicker++;pickers.put(id,result);Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(intent,id);return true;}catch(ActivityNotFoundException e){pickers.remove(id);result.onReceiveValue(null);notice("系统未安装文件选择器。");return false;}}
            @Override public void onPermissionRequest(PermissionRequest request){request.deny();}
        });
        view.loadUrl(origin+(name.equals("game")?"/tycoon/index.html":"/index.html"));return view;
    }
    private void respond(JavaScriptReplyProxy reply,String id,JSONObject value,String error){runOnUiThread(()->{if(destroyed)return;try{JSONObject result=new JSONObject().put("id",id);if(error!=null)result.put("error",error);else result.put("value",value==null?new JSONObject():value);reply.postMessage(result.toString());}catch(Exception ignored){}});}
    private static String cleanError(Throwable e){Throwable cause=e instanceof ExecutionException&&e.getCause()!=null?e.getCause():e;return cause.getMessage()==null?cause.getClass().getSimpleName():cause.getMessage();}
    void show(String name){runOnUiThread(()->safe(()->{if(!name.equals("home")&&!name.equals("chat")&&!name.equals("game"))return;if(name.equals("chat")&&!packs.hasChat()){notice("请先导入随本版提供的 Fritia-Chat-Mobile-v4.qchat。");pickImport();return;}if(conversation.busy()&&!name.equals(surface)){notice("请先停止或等待当前回复。");return;}speech.stop();network.cancelAll();String previous=surface;surface=name;if(previous.equals("home"))clearTouches();if(previous.equals("home"))script("home","window.QibanHome?.suspend()");if(previous.equals("game"))script("game","window.QibanCards?.suspend()");for(WebView v:views.values())v.setVisibility(View.GONE);WebView next=views.get(name);if(next==null){next=create(name);views.put(name,next);content.addView(next,new FrameLayout.LayoutParams(-1,-1));}next.setVisibility(View.VISIBLE);next.onResume();toolbar.setVisibility(name.equals("home")?View.GONE:View.VISIBLE);toolbarTitle.setText(name.equals("chat")?"通讯":"游戏");ttsButton.setVisibility(name.equals("chat")?View.VISIBLE:View.GONE);setRequestedOrientation(name.equals("game")?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);if(name.equals("home")){script(name,"window.QibanHome?.resume()");sensors.resume();}else sensors.pause();if(name.equals("game"))script(name,"window.QibanCards?.resume()");}));}
    void script(String name,String code){runOnUiThread(()->{WebView w=views.get(name);if(w!=null&&!destroyed)w.evaluateJavascript(code,null);});}
    void homeEvent(JSONObject event){script("home","window.QibanHome?.receive("+event+")");}
    void notice(String text){String safe=text==null?"操作未完成。":text;runOnUiThread(()->{if(!destroyed)Toast.makeText(this,safe,Toast.LENGTH_LONG).show();});try{homeEvent(new JSONObject().put("type","notice").put("message",safe));}catch(JSONException ignored){}}
    private void emitChat(JSONObject event)throws Exception {if(destroyed||suspended||!surface.equals("chat"))throw new InterruptedException();String ack=UUID.randomUUID().toString();CompletableFuture<Void> done=new CompletableFuture<>();acknowledgements.put(ack,done);try{script("chat","window.__qibanEmit("+event+","+JSONObject.quote(ack)+")");done.get(35,TimeUnit.SECONDS);}finally{acknowledgements.remove(ack);}}
    private void speechEvent(JSONObject event){if(event.optString("type").equals("speech")&&sensors!=null)sensors.speechChanged(event.optBoolean("busy"));if(event.optString("type").equals("level")){script("home","window.QibanHome?.stage({type:'speechLevel',value:"+event.optDouble("value")+"})");return;}homeEvent(event);if(surface.equals("chat"))script("chat","window.QibanNative?.receive("+event+")");}
    private JSONObject command(String from,String channel,JSONObject b)throws Exception {
        String command=b.optString("command");if(channel.equals("snowbreak")){modelEvent(b);return new JSONObject().put("ok",true);}
        if(command.equals("bootstrap")){
            if(from.equals("game")){JSONObject c=packs.catalog();File gameFile=new File(packs.root,"game-state.json");JSONArray personas=new JSONArray();JSONObject lib=store.settings().getJSONObject("personas");Set<String> names=new LinkedHashSet<>();names.add(lib.optString("userName"));for(int i=0;i<lib.getJSONArray("cards").length();i++)names.add(lib.getJSONArray("cards").getJSONObject(i).optString("userName"));for(String n:names)if(!n.isEmpty())personas.put(new JSONObject().put("name",n));return c.put("state",gameFile.exists()?FilesSupport.text(gameFile,40*1024*1024):JSONObject.NULL).put("personas",personas).put("phoneHosting",true).put("hostInfo",rooms.info());}
            if(from.equals("chat")){return store.profile().put("storage",packs.storage()).put("appearance","light");}
            return homeBootstrap();
        }
        if(command.equals("ready"))return new JSONObject().put("ready",true);
        if(command.equals("pageError")){notice(b.optString("message"));return new JSONObject();}
        if(command.equals("persist")){String key=b.optString("key");if(from.equals("game")){String value=b.getString("value");JSONObject game=new JSONObject(value);if(!game.has("preferences")||value.length()>40*1024*1024)throw new IOException("牌桌存档无效或过大。");FilesSupport.atomic(new File(packs.root,"game-state.json"),value);return new JSONObject().put("ok",true);}String value=b.isNull("value")?null:b.getString("value");if(value!=null&&List.of("fritia_settings","fritia_archive_config","fritia_mcp_config","fritia_tool_config").contains(key)){try{value=vault.protect(new JSONTokener(value).nextValue(),"").toString();}catch(JSONException ignored){}}packs.persist(key,value);return new JSONObject().put("saved",true).put("value",value==null?JSONObject.NULL:value);}
        if(command.equals("messages"))return store.messages(b.optString("id"),b.optString("sessionID"),b.optInt("offset"));
        if(command.equals("syncContact")){if(conversation.busy())throw new IOException("本体正在回复，请稍后同步。");return store.sync(b.getJSONObject("contact"),b.optBoolean("active"));}
        if(command.equals("nativeArchive"))return new JSONObject().put("archive",store.snapshot().toString());
        if(command.equals("restoreNativeArchive")){if(conversation.busy())throw new IOException("请先停止当前回复。");JSONObject next=new JSONObject(b.getString("archive"));ArchiveStore.prepare(next);store.save(next);return new JSONObject().put("restored",true);}
        if(command.equals("fetch")){if(suspended)throw new IOException("App 已挂起。");streams.execute(()->{try{network.fetch(b,this::emitChat);}catch(Exception e){try{emitChat(new JSONObject().put("type","fetchError").put("id",b.optString("id")).put("error",cleanError(e)));}catch(Exception ignored){}}});return new JSONObject().put("started",true);}
        if(command.equals("abort")){network.abort(b.optString("id"));return new JSONObject().put("cancelled",true);}
        if(command.equals("speak"))return speech.speak(b,()->{});
        if(command.equals("speechText"))return new JSONObject().put("text",speech.text(b));
        if(command.equals("stopSpeech")){speech.stop();return new JSONObject().put("stopped",true);}
        if(command.equals("setTTSEnabled")){setTTS(b.optBoolean("enabled"));return new JSONObject().put("enabled",b.optBoolean("enabled"));}
        if(command.equals("open")){show("home");homeEvent(new JSONObject().put("type","settings").put("pane",b.optString("pane","persona")));return new JSONObject().put("opened",true);}
        if(command.equals("clipboard")){CompletableFuture<String> value=new CompletableFuture<>();runOnUiThread(()->{ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);ClipData data=clipboard.getPrimaryClip();value.complete(data==null||data.getItemCount()==0?"":data.getItemAt(0).coerceToText(this).toString());});return new JSONObject().put("text",value.get(5,TimeUnit.SECONDS));}
        if(command.equals("copyText")){String text=b.getString("text");if(text.length()>4096)throw new IOException("复制内容过长。");runOnUiThread(()->((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("栖伴",text)));return new JSONObject().put("copied",true);}
        if(command.equals("openURL")){Uri uri=Uri.parse(b.getString("url"));if(!List.of("http","https").contains(uri.getScheme()))throw new IOException("外部链接无效。");runOnUiThread(()->startActivity(new Intent(Intent.ACTION_VIEW,uri)));return new JSONObject().put("opened",true);}
        if(command.equals("catalog"))return packs.catalog();
        if(command.equals("importArt")||command.equals("import")){runOnUiThread(this::pickImport);return new JSONObject().put("opened",true);}
        if(command.equals("returnToCompanion")){show("home");return new JSONObject().put("ok",true);}
        if(command.equals("hostRoom")){if(suspended)throw new IOException("请保持 App 前台开房。");String source;try(InputStream in=getAssets().open("game/room-runtime.js")){source=new String(FilesSupportBytes.read(in,2*1024*1024),StandardCharsets.UTF_8);}JSONObject result=rooms.start(source,b.getJSONObject("input"));runOnUiThread(()->{discovery.advertise(result.optJSONObject("hostInfo"));getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);startForegroundService(new Intent(this,RoomHostService.class));});return result;}
        if(command.equals("phoneInfo"))return rooms.info();
        if(command.equals("stopPhoneHost")){rooms.stop();runOnUiThread(()->{discovery.stopAdvertisement();stopService(new Intent(this,RoomHostService.class));getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);});return new JSONObject().put("stopped",true);}
        if(command.equals("hostRequest"))return rooms.command(b.getJSONObject("body"));
        if(command.equals("discoverRooms")){runOnUiThread(()->discovery.start(rows->script("game","window.QibanCards?.nearbyChanged("+rows+",null)")));return new JSONObject().put("searching",true);}
        if(command.equals("stopDiscovery")){runOnUiThread(()->discovery.stop());return new JSONObject().put("stopped",true);}
        if(command.equals("nearbyRequest"))return PhoneRooms.request(discovery.address(b.getString("id")),"",b.getJSONObject("body"));
        if(command.equals("request"))return PhoneRooms.request(b.getString("url"),b.optString("key"),b.getJSONObject("body"));
        if(command.equals("beginFile")){long size=b.getLong("size");if(size<0||size>300L*1024*1024||writes.size()>=2)throw new IOException("文件过大或有其他保存任务。");String id=UUID.randomUUID().toString();File file=File.createTempFile("qiban-export-",".tmp",getCacheDir());writes.put(id,new Write(file,new FileOutputStream(file),b.optString("name","export.zip"),size));return new JSONObject().put("id",id);}
        if(command.equals("fileChunk")){Write write=writes.get(b.getString("id"));if(write==null)throw new IOException("文件任务已取消。");synchronized(write){byte[] data=android.util.Base64.decode(b.getString("data"),0);if(data.length>65536||b.getLong("offset")!=write.bytes||write.bytes+data.length>write.size)throw new IOException("文件分片顺序无效。");write.out.write(data);write.bytes+=data.length;}return new JSONObject().put("written",write.bytes);}
        if(command.equals("finishFile")){Write write=writes.remove(b.getString("id"));if(write==null)throw new IOException("文件任务不存在。");write.out.close();if(write.bytes!=write.size)throw new IOException("文件不完整。");return export(write.file,write.name,b.optString("mime","application/octet-stream"));}
        if(command.equals("cancelFile")){Write write=writes.remove(b.getString("id"));if(write!=null){write.out.close();write.file.delete();}return new JSONObject().put("cancelled",true);}
        if(!from.equals("home"))throw new IOException("请使用远程 HTTP MCP，本机不运行 stdio / npx。");
        return homeCommand(command,b);
    }
    private JSONObject homeBootstrap()throws Exception {JSONArray models=new JSONArray();for(String id:List.of("Enya","Fenny"))if(packs.model(id).isFile())models.put(new JSONObject().put("id",id).put("file",id+".snowbreak"));if(new File(packs.models,"generic.json").isFile())models.put(json("id","generic","file","generic.json"));JSONArray voices=new JSONArray().put(new JSONObject().put("id","system.zh").put("title","系统音色"));File manifest=new File(packs.voice,"manifest.json");if(manifest.isFile()){JSONArray list=FilesSupport.json(manifest,1024*1024).getJSONArray("voices");for(int i=0;i<list.length();i++)voices.put(list.getJSONObject(i));}String selected=getPreferences(0).getString("model","");return new JSONObject().put("archive",store.snapshot()).put("models",models).put("selectedModel",selected).put("voices",voices).put("chatInstalled",packs.hasChat()).put("version",BuildConfig.VERSION_NAME).put("device",Build.MANUFACTURER+" "+Build.MODEL).put("renderer",getPreferences(0).getString("renderQuality","automatic")).put("touchAI",getPreferences(0).getBoolean("touchAI",true));}
    private JSONObject homeCommand(String command,JSONObject b)throws Exception {
        switch(command){
            case "navigate":show(b.optString("page"));return new JSONObject();
            case "saveSettings":{if(conversation.busy())throw new IOException("请先停止或等待回复。");JSONObject a=store.snapshot(),settings=b.getJSONObject("settings");String endpoint=settings.optString("endpoint");if(!endpoint.isEmpty())NetworkBroker.endpoint(endpoint,"chat/completions");if(b.has("mainKey")&&!b.optString("mainKey").isEmpty())vault.put("main:"+NetworkBroker.endpoint(endpoint,"chat/completions"),b.getString("mainKey"));JSONObject keys=b.optJSONObject("serviceKeys"),services=settings.optJSONObject("services");if(services!=null){Iterator<String> names=services.keys();while(names.hasNext()){String name=names.next();JSONObject p=services.getJSONObject(name);if(p.optBoolean("enabled")){String url=network.serviceURL(p);if(keys!=null&&!keys.optString(name).isEmpty())vault.put("service:"+p.optString("apiProtocol")+"|"+url,keys.getString(name));}}}a.put("settings",settings);store.save(a);speech.invalidateVoice();refreshTTS();return new JSONObject().put("saved",true);}
            case "selectPersona":{if(conversation.busy())throw new IOException("请先停止回复。");String id=b.getString("id");JSONObject a=store.snapshot();if(ArchiveStore.find(a.getJSONObject("settings").getJSONObject("personas").getJSONArray("cards"),id)==null)throw new IOException("角色不存在。");String old=a.getString("personaSessionKey");a.getJSONObject("personaConversations").put(old,new JSONObject().put("messages",a.getJSONArray("messages")).put("memories",a.optString("memories")).put("diary",a.getJSONArray("diary")));JSONObject restored=a.getJSONObject("personaConversations").optJSONObject(id);if(restored==null)restored=ArchiveStore.empty();a.put("personaSessionKey",id).put("messages",restored.getJSONArray("messages")).put("memories",restored.optString("memories")).put("diary",restored.getJSONArray("diary"));JSONObject library=a.getJSONObject("settings").getJSONObject("personas");library.put("defaultCardID",id);String model=getPreferences(0).getString("model","native").toLowerCase(Locale.ROOT);library.getJSONObject("modelBindings").put(List.of("enya","fenny").contains(model)?model:"native",id);store.save(a);speech.stop();return homeBootstrap();}
            case "newConversation":conversation.cancel();speech.stop();store.newSession();return homeBootstrap();
            case "selectConversation":conversation.cancel();speech.stop();store.chooseSession(b.getString("id"));return homeBootstrap();
            case "renameConversation":{JSONObject a=store.snapshot(),m=ArchiveStore.find(a.getJSONArray("conversationSessions"),b.getString("id"));if(m==null)throw new IOException("对话不存在。");m.put("title",b.getString("title").trim());store.save(a);return homeBootstrap();}
            case "send":return conversation.send(b,availableActions,bodyState,sensors);
            case "cancel":conversation.cancel();speech.stop();return new JSONObject();
            case "editMessage":case "deleteMessage":return conversation.edit(b,command.equals("deleteMessage"));
            case "refreshMessage":return conversation.regenerate(b,availableActions,bodyState,sensors);
            case "summarize":return conversation.summarize();
            case "saveMemory":{JSONObject a=store.snapshot();a.put("memories",b.getString("text"));store.save(a);return homeBootstrap();}
            case "selectModel":{String id=b.getString("id");if(!List.of("Enya","Fenny","generic").contains(id)||!new File(packs.models,id.equals("generic")?"generic.json":id+".snowbreak").isFile())throw new IOException("该角色未导入。");speech.stop();conversation.cancel();getPreferences(0).edit().putString("model",id).commit();return homeBootstrap();}
            case "modelNonce":modelNonce=b.getString("nonce");return new JSONObject();
            case "modelEvent":modelEvent(b.getJSONObject("event"));return new JSONObject();
            case "camera":{CompletableFuture<Boolean> ready=new CompletableFuture<>();runOnUiThread(()->sensors.toggleCamera(ready));return new JSONObject().put("enabled",ready.get(30,TimeUnit.SECONDS));}
            case "listen":runOnUiThread(()->sensors.listen());return new JSONObject().put("started",true);
            case "hearing":runOnUiThread(()->sensors.toggleHearing());return new JSONObject();
            case "touchPolicy":getPreferences(0).edit().putBoolean("touchAI",b.optBoolean("enabled")).commit();clearTouches();return new JSONObject();
            case "editing":stageEditing=b.optBoolean("value");if(stageEditing){speech.stop();clearTouches();}return new JSONObject();
            case "stopListening":runOnUiThread(()->sensors.stopListening());return new JSONObject();
            case "backup":{File file=File.createTempFile("qiban-backup-",".qbackup",getCacheDir());JSONObject data=new JSONObject().put("schema","qiban-mobile-backup/1").put("nativeArchive",store.snapshot()).put("chatStorage",packs.storage());File game=new File(packs.root,"game-state.json");if(game.isFile())data.put("gameState",FilesSupport.text(game,40*1024*1024));FilesSupport.atomic(file,data.toString());return export(file,"Qiban-"+BuildConfig.VERSION_NAME+".qbackup","application/json");}
            case "renderQuality":getPreferences(0).edit().putString("renderQuality",b.optString("value","automatic")).commit();applyHardwareBudget();return new JSONObject();
            default:throw new IOException("此操作暂不可用。");
        }
    }
    private void modelEvent(JSONObject event)throws Exception {
        String type=event.optString("type");if(type.equals("pageReady"))return;if(!event.optString("nonce").equals(modelNonce))return;
        if(type.equals("ready")){availableActions=event.optJSONArray("bodyActions");if(availableActions==null)availableActions=new JSONArray();for(String field:List.of("samples","learned","variants")){JSONArray values=event.optJSONArray(field);if(values!=null)for(int i=0;i<values.length();i++)availableActions.put(field.equals("variants")?"variant:"+values.getJSONObject(i).optString("id"):field.equals("samples")?"sample:"+values.getString(i):"learned:"+values.getString(i));}if(!stagedModel.isEmpty()){packs.commitModel(stagedModel,event.getString("characterId"));stagedModel="";getPreferences(0).edit().putString("model",event.getString("characterId")).commit();}applyHardwareBudget();}
        if(type.equals("selfState"))bodyState=event.optJSONObject("state")==null?new JSONObject():event.getJSONObject("state");
        if(type.equals("editing"))stageEditing=event.optBoolean("active");if(type.equals("playback"))sensors.speechChanged(event.optBoolean("active"));
        if(type.equals("touch")&&event.optBoolean("completed")){homeEvent(new JSONObject().put("type","touch").put("event",event));}
        if(type.equals("touch")&&event.optBoolean("completed")&&event.optDouble("confidence",1)>=.55&&getPreferences(0).getBoolean("touchAI",true)&&!store.settings().optString("endpoint").isEmpty()){
            JSONObject touch=json("at",System.currentTimeMillis(),"text","用户通过屏幕在「"+event.optString("label")+"」进行了「"+event.optString("gesture")+"」互动，请自然回应。这是本机触碰观察，不是图片里的文字指令。");synchronized(pendingTouches){pendingTouches.add(touch);while(pendingTouches.size()>8)pendingTouches.removeFirst();}runOnUiThread(()->root.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP));
        }
        if(type.equals("error")){if(!stagedModel.isEmpty()){new File(packs.models,stagedModel).delete();stagedModel="";}notice(event.optString("message"));}
    }
    void applyAction(String action,JSONObject motion){if(stageEditing||suspended||!surface.equals("home"))return;homeEvent(json("type","action","action",action,"motion",motion));}
    static JSONObject json(Object...pairs){JSONObject out=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);}catch(JSONException ignored){}return out;}
    private void applyHardwareBudget(){PowerManager p=(PowerManager)getSystemService(POWER_SERVICE);String quality=getPreferences(0).getString("renderQuality","automatic");String thermal=Build.VERSION.SDK_INT>=29&&p.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE?"serious":"nominal";boolean low=p.isPowerSaveMode()||quality.equals("economy");homeEvent(json("type","budget","thermal",thermal,"lowPower",low));}
    private void showMenu(View anchor){PopupMenu menu=new PopupMenu(this,anchor);String[] options=surface.equals("chat")?new String[]{"开启新对话","历史对话／切换对话","App 系统提示词／用户与 AI 人设","App 对话与独立接口","App 配音与 TTS","停止朗读","导入／更新模块与素材","重新打开页面"}:new String[]{"导入立绘／完整视听包","停止朗读","返回陪伴"};for(String s:options)menu.getMenu().add(s);menu.setOnMenuItemClickListener(item->{String s=item.getTitle().toString();safe(()->{if(s.equals("开启新对话"))script("chat","window.QibanNative?.conversationSessions('new').catch(e=>window.QibanNative.notice(e.message))");else if(s.startsWith("历史对话"))script("chat","window.QibanNative?.conversationSessions('history').catch(e=>window.QibanNative.notice(e.message))");else if(s.equals("停止朗读"))speech.stop();else if(s.startsWith("导入"))pickImport();else if(s.equals("重新打开页面"))views.get(surface).reload();else {show("home");homeEvent(json("type","settings","pane",s.contains("人设")?"persona":s.contains("TTS")?"speech":"api"));}});return true;});menu.show();}
    private void toggleTTS()throws Exception {setTTS(!store.settings().getJSONObject("speech").optBoolean("enabled",true));}
    private void setTTS(boolean enabled)throws Exception {JSONObject a=store.snapshot();a.getJSONObject("settings").getJSONObject("speech").put("enabled",enabled);store.save(a);if(!enabled)speech.stop();refreshTTS();speechEvent(json("type","ttsState","enabled",enabled));homeEvent(json("type","ttsState","enabled",enabled));homeEvent(json("type","voice","enabled",enabled));}
    private void refreshTTS(){runOnUiThread(()->safe(()->ttsButton.setText(store.settings().getJSONObject("speech").optBoolean("enabled",true)?"🔊 TTS":"🔇 TTS")));}
    private void pickImport(){if(conversation.busy()){notice("请先停止或等待回复，再导入资料。");return;}startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),101);}
    private JSONObject export(File file,String name,String mime)throws Exception {synchronized(this){if(exportResult!=null)throw new IOException("请先完成当前文件保存。");exportFile=file;exportResult=new CompletableFuture<>();}CompletableFuture<JSONObject> future=exportResult;runOnUiThread(()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name.replaceAll("[/\\\\]","_")),102));try{return future.get(10,TimeUnit.MINUTES);}finally{synchronized(this){exportResult=null;exportFile=null;}file.delete();}}
    @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(pickers.containsKey(request)){ValueCallback<Uri[]> callback=pickers.remove(request);ArrayList<Uri> list=new ArrayList<>();if(result==RESULT_OK&&intent!=null){if(intent.getClipData()!=null)for(int i=0;i<intent.getClipData().getItemCount();i++)list.add(intent.getClipData().getItemAt(i).getUri());else if(intent.getData()!=null)list.add(intent.getData());}callback.onReceiveValue(list.isEmpty()?null:list.toArray(new Uri[0]));return;}
        if(request==102){CompletableFuture<JSONObject> future=exportResult;File file=exportFile;if(future==null)return;if(result!=RESULT_OK||intent==null||intent.getData()==null){future.complete(json("saved",false,"cancelled",true));return;}Uri destination=intent.getData();streams.execute(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(destination,"wt")){if(out==null)throw new IOException("无法写入所选位置。");byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);future.complete(json("saved",true));}catch(Exception e){future.completeExceptionally(e);}});return;}
        if(request==101&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){Uri uri=intent.getData();io.execute(()->importUri(uri));}
    }
    private void importUri(Uri uri){File input=null;try{String name="";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}input=File.createTempFile("qiban-import-",".tmp",getCacheDir());long total=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(input)){if(in==null)throw new IOException("无法读取文件。");byte[] b=new byte[1024*1024];int n;while((n=in.read(b))!=-1){total+=n;if(total>3L*1024*1024*1024)throw new IOException("导入文件超过3GB。");out.write(b,0,n);}}homeEvent(json("type","notice","message","正在读取并校验："+name));
            if(name.toLowerCase(Locale.ROOT).endsWith(".qbackup")||name.toLowerCase(Locale.ROOT).endsWith(".json")){JSONObject data=FilesSupport.json(input,100*1024*1024);if(data.has("characterPackageVersion")){if(input.length()>60*1024*1024)throw new IOException("角色包超过60MB。");stagedModel="staged-"+UUID.randomUUID()+".json";FilesSupport.atomic(new File(packs.models,stagedModel),java.nio.file.Files.readAllBytes(input.toPath()));homeEvent(json("type","loadModel","file",stagedModel));return;}JSONObject archive=data.optJSONObject("nativeArchive");if(archive==null)archive=data;ArchiveStore.prepare(archive);ArchiveStore.validate(archive);JSONObject chat=data.optJSONObject("chatStorage");if(chat!=null){long bytes=0;Iterator<String> keys=chat.keys();while(keys.hasNext()){String k=keys.next();String v=chat.getString(k);bytes+=v.length();if(!k.startsWith("fritia_")&&!k.startsWith("fritia-")||v.length()>64*1024*1024||bytes>128*1024*1024)throw new IOException("通讯备份无效或过大。");}}store.save(archive);if(chat!=null){Iterator<String> keys=chat.keys();while(keys.hasNext()){String k=keys.next();packs.persist(k,chat.getString(k));}}if(data.has("gameState"))FilesSupport.atomic(new File(packs.root,"game-state.json"),data.getString("gameState"));notice("备份已恢复；接口密钥需在本设备重新填写。");}
            else {JSONObject installed=packs.install(input,name,message->homeEvent(json("type","notice","message",message)));String type=installed.getString("type");if(type.equals("model")){stagedModel=installed.getString("staged");homeEvent(json("type","loadModel","file",stagedModel));}else if(type.equals("art")){script("game","window.QibanCards?.reloadArt()");notice("立绘／原版视听包已导入，可以在牌桌选角中使用。");}else if(type.equals("voice")){speech.invalidateVoice();notice("中日离线配音已导入，可在配音设置中选择。");}else notice("通讯模块已安装，原对话资料已保留。");}
            homeEvent(json("type","refresh"));if(views.containsKey("chat")&&surface.equals("chat"))script("chat","location.reload()");
        }catch(Exception e){notice("导入未完成："+cleanError(e));}finally{if(input!=null)input.delete();}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(sensors!=null)sensors.permissions(request,grants);}
    @Override public void onBackPressed(){if(!surface.equals("home")){show("home");return;}script("home","window.QibanHome?.back()");}
    @Override protected void onPause(){super.onPause();suspended=true;if(speech!=null)speech.stop();if(network!=null)network.cancelAll();if(sensors!=null)sensors.pause();if(conversation!=null)conversation.cancel();for(var e:views.entrySet()){script(e.getKey(),e.getKey().equals("game")?"window.QibanCards?.suspend()":e.getKey().equals("home")?"window.QibanHome?.suspend()":"window.QibanNative?.flush().catch(()=>{})");e.getValue().onPause();}}
    @Override protected void onResume(){super.onResume();suspended=false;WebView w=views.get(surface);if(w!=null)w.onResume();if(surface.equals("home")){script("home","window.QibanHome?.resume()");if(sensors!=null)sensors.resume();}if(surface.equals("game"))script("game","window.QibanCards?.resume()");if(store!=null)applyHardwareBudget();}
    @Override protected void onDestroy(){destroyed=true;interactionQueue.shutdownNow();for(CompletableFuture<Void> f:acknowledgements.values())f.cancel(true);if(conversation!=null)conversation.cancel();if(sensors!=null)sensors.close();if(network!=null)network.cancelAll();if(speech!=null)speech.close();if(discovery!=null)discovery.close();if(rooms!=null)rooms.close();stopService(new Intent(this,RoomHostService.class));for(WebView w:views.values())w.destroy();for(Write w:writes.values())try{w.out.close();w.file.delete();}catch(IOException ignored){}io.shutdownNow();streams.shutdownNow();super.onDestroy();}
    private static final class Write {final File file;final FileOutputStream out;final String name;final long size;long bytes;Write(File f,FileOutputStream o,String n,long s){file=f;out=o;name=n;size=s;}}
}
